import { buildModel, draftEmail, interpretResponse, validateCitations } from '/engine.js';

const state = { evidence: [], groups: [], selected: 0, config: null, statuses: {}, events: JSON.parse(localStorage.getItem('decision-events') || '[]'), activeRequirement: null };
const $ = id => document.getElementById(id);
const escapeHtml = value => String(value).replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));

async function init() {
  const payload = await fetch('/data/evidence.json').then(r => r.json());
  state.evidence = payload.records;
  $('importance').addEventListener('input', e => $('importance-output').value = `${e.target.value} / 10`);
  $('config-form').addEventListener('submit', generate);
  $('edit-config').addEventListener('click', () => { $('setup').classList.remove('hidden'); $('workspace').classList.add('hidden'); });
  document.querySelectorAll('.nav').forEach(b => b.addEventListener('click', () => showView(b.dataset.view)));
  document.querySelectorAll('[data-close]').forEach(b => b.addEventListener('click', () => b.closest('dialog').close()));
  renderMemory();
}

function addEvent(type, title, description, data={}) {
  state.events.unshift({ id: crypto.randomUUID(), type, title, description, data, at: new Date().toISOString(), provenance:'Genuine application event' });
  localStorage.setItem('decision-events', JSON.stringify(state.events));
  renderMemory();
}

function generate(event) {
  event?.preventDefault();
  state.config = { vehicle:$('vehicle').value, market:$('market').value, months:Number($('months').value), people:Number($('people').value), importance:Number($('importance').value) };
  state.groups = buildModel(state.evidence, state.config, state.statuses);
  state.selected = 0;
  addEvent('project-created', 'Product context evaluated', `${state.config.vehicle} · ${state.config.market} · ${state.config.months} months · ${state.config.people} people · deadline importance ${state.config.importance}/10`, state.config);
  addEvent('ranking-calculated', 'Requirements generated and ranked', `${state.groups.length} evidence-derived feature groups created. No engineering feasibility was assumed.`);
  $('setup').classList.add('hidden'); $('workspace').classList.remove('hidden'); $('memory').classList.add('hidden');
  document.querySelectorAll('.nav').forEach(n => n.classList.toggle('active', n.dataset.view === 'workspace'));
  render();
}

function showView(view) {
  if (view === 'memory') { $('setup').classList.add('hidden'); $('workspace').classList.add('hidden'); $('memory').classList.remove('hidden'); }
  else if (state.config) { $('setup').classList.add('hidden'); $('memory').classList.add('hidden'); $('workspace').classList.remove('hidden'); }
  document.querySelectorAll('.nav').forEach(n => n.classList.toggle('active', n.dataset.view === view));
}

function render() {
  const c=state.config, group=state.groups[state.selected];
  $('project-title').textContent = `${c.vehicle} requirement strategy · ${c.market}`;
  $('context-chips').innerHTML = `<span class="chip">${c.months} months</span><span class="chip">${c.people} people</span><span class="chip">Deadline importance ${c.importance}/10</span>`;
  const relevant=state.evidence.filter(r=>r.vehicle===c.vehicle&&r.market===c.market), low=relevant.filter(r=>r.quality==='low').length;
  $('integrity').textContent = `✓ Citation integrity verified · ${relevant.length.toLocaleString()} contextual records · ${low.toLocaleString()} low-quality rows retained but excluded · frequency deduplicated by feedback ID`;
  $('group-list').innerHTML = state.groups.map((g,i)=>`<button class="group-button ${i===state.selected?'active':''}" data-group="${i}"><strong>${escapeHtml(g.name)}</strong><span>${g.requirements.length} supported requirement${g.requirements.length===1?'':'s'}</span></button>`).join('');
  document.querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>{state.selected=Number(b.dataset.group);render()});
  if (!group) { $('group-title').textContent='No supported groups'; $('group-description').textContent='Try another vehicle or market.'; $('requirements').innerHTML=''; return; }
  $('group-title').textContent=group.name; $('group-description').textContent=group.description; $('req-count').textContent=group.requirements.length;
  $('requirements').innerHTML=group.requirements.map(r=>`<article class="requirement"><div class="rank">#${r.rank}</div><div><h3>${escapeHtml(r.statement)}</h3><div class="meta"><span><strong>${r.frequency}</strong> unique evidence records</span><span>TTM fit <strong>${r.fitScore}/100</strong></span><span>${escapeHtml(r.owner.name)}</span><span class="badge ${r.status}">${r.status.replaceAll('-',' ')}</span></div></div><div class="actions"><button data-detail="${r.id}">Evidence & reasoning</button><button class="validate" data-validate="${r.id}">Check feasibility</button></div></article>`).join('');
  document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>openDetail(findRequirement(b.dataset.detail)));
  document.querySelectorAll('[data-validate]').forEach(b=>b.onclick=()=>openValidation(findRequirement(b.dataset.validate)));
  $('integrity').classList.toggle('error', !validateCitations(state.groups,state.evidence));
