  $('validation-dialog').showModal();
  $('interpret').onclick=()=>{const result=interpretResponse($('stakeholder-response').value);$('interpretation').innerHTML=`<div class="evidence-box"><h3>AI INTERPRETATION · PM CONFIRMATION REQUIRED</h3><p>Status: <strong>${result.status.replaceAll('-',' ')}</strong></p><p>${escapeHtml(result.summary)}</p><button id="confirm-response" class="primary">Confirm and recalculate <span>→</span></button></div>`;$('confirm-response').onclick=()=>confirmResponse(r,result)};
  if(r.status==='not-checked'){state.statuses[r.feature]='awaiting';addEvent('validation-requested','Feasibility draft created',`${r.feature} routed to ${r.owner.name}; email remains unsent.`);render()}
}

function confirmResponse(r,result){
  if(result.status==='unclear'){alert('The response is unclear. Ask the stakeholder for a feasibility conclusion before confirming.');return}
