const GROUP_RULES = [
  ['Interior & Comfort', /seat|comfort|lumbar|climat|blower|acoustic|noise|audio|sound|belt|mirror|console|storage|interior|cabin|cupholder/i],
  ['Exterior & Utility', /exterior|roof|trunk|tailgate|door|light|paint|wheel|tire|luggage|cargo|compartment|fold/i],
  ['Digital Experience & Controls', /digital|app|bluetooth|carplay|android|connected|remote|mobile|phone|operat|control|touch|display|cluster|parking|automatic-hold|speed limit|button|owner's manual|camera|infotainment|idrive|navigation/i]
];

const ENTITY_RULES = [
  ['Software & Connected Services', /app|digital|bluetooth|carplay|connected|remote|operating system|display|touch|camera/i],
  ['Interior Engineering', /seat|comfort|lumbar|climat|blower|console|storage|mirror|belt|audio|sound/i],
  ['Chassis Engineering', /handling|riding|chassis|steer|brake|pedal|suspension|stability/i],
  ['E-Mobility Engineering', /electric|charging|battery|range|efficiency/i],
  ['Body Engineering', /exterior|roof|trunk|tailgate|door|luggage|compartment|space/i]
];

const monthsFor = feature => /app|software|display|touch|operating|bluetooth|carplay|manual/i.test(feature) ? 6
  : /seat|console|storage|mirror|belt|audio|climat|control|camera/i.test(feature) ? 12
  : /chassis|suspension|body|roof|luggage|battery|drivetrain/i.test(feature) ? 24 : 15;

export function groupFor(feature) {
  return GROUP_RULES.find(([, rule]) => rule.test(feature))?.[0] || 'Driving & Powertrain';
}

export function entityFor(feature) {
  const match = ENTITY_RULES.find(([, rule]) => rule.test(feature));
  return { name: match?.[0] || 'Product Integration', confidence: match ? 'medium' : 'low', reason: match ? `The feature classification “${feature}” matches this function’s typical ownership.` : 'Ownership crosses domains and requires PM confirmation.' };
}

function requirementStatement(feature, records) {
  const types = new Set(records.map(r => r.feedbackType));
  if ([...types].some(t => /Difficult/i.test(t))) return `Make ${feature.toLowerCase()} easier and more predictable to use`;
  if ([...types].some(t => /Want/i.test(t))) return `Improve ${feature.toLowerCase()} to address documented customer requests`;
  return `Preserve and strengthen customer satisfaction with ${feature.toLowerCase()}`;
}

export function buildModel(records, config, statuses = {}) {
  const relevant = records.filter(r => r.vehicle === config.vehicle && r.market === config.market && r.quality !== 'low' && r.feature);
  const byFeature = new Map();
  for (const record of relevant) {
    if (!byFeature.has(record.feature)) byFeature.set(record.feature, []);
    byFeature.get(record.feature).push(record);
  }
  const maxFrequency = Math.max(1, ...[...byFeature.values()].map(items => new Set(items.map(x => x.feedbackId)).size));
  const requirements = [...byFeature].map(([feature, items]) => {
    const unique = [...new Map(items.map(item => [item.feedbackId, item])).values()];
    const months = monthsFor(feature);
    const peopleNeeded = Math.max(2, Math.ceil(months / 3));
    const frequencyScore = Math.round((unique.length / maxFrequency) * 100);
    const scheduleRatio = (config.months * Math.max(1, config.people)) / (months * peopleNeeded);
    const fitScore = Math.round(Math.min(100, scheduleRatio * 70));
    const importance = Number(config.importance) / 10;
    let score = Math.round(frequencyScore * (0.75 - importance * 0.25) + fitScore * (0.25 + importance * 0.25));
    if (statuses[feature] === 'not-feasible' || statuses[feature] === 'pm-rejected') score = -1;
    if (statuses[feature] === 'conditional') score -= 12;
    const owner = entityFor(feature);
    return {
      id: `req-${feature.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '')}`,
      feature,
      group: groupFor(feature),
      statement: requirementStatement(feature, items),
      frequency: unique.length,
      score,
      estimatedMonths: months,
      estimatedPeople: peopleNeeded,
      fitScore,
      status: statuses[feature] || 'not-checked',
      owner,
      citations: unique.slice(0, 8).map(r => ({ evidenceId: r.evidenceId, file: r.sourceFile, sheet: r.sheet, row: r.row, excerpt: r.text, feedbackId: r.feedbackId })),
      whyExists: `${unique.length} unique, relevant ${config.market} feedback record${unique.length === 1 ? '' : 's'} support this requirement for ${config.vehicle}.`,
      whyRanked: `Its deduplicated evidence frequency is ${unique.length}. The AI planning estimate is ${months} months with about ${peopleNeeded} people. Against the PM’s ${config.months}-month target, ${config.people}-person team and ${config.importance}/10 deadline importance, its time-to-market fit is ${fitScore}/100.`,
      inferenceLabels: ['Requirement wording: AI-derived', 'Time-to-market fit: AI planning estimate', 'Ownership: AI-inferred']
    };
  }).filter(r => r.frequency > 0 && r.score >= 0);

  const groups = new Map();
  for (const requirement of requirements) {
    if (!groups.has(requirement.group)) groups.set(requirement.group, []);
    groups.get(requirement.group).push(requirement);
  }
  return [...groups].map(([name, items]) => ({
    name,
    description: `Requirements mapped to the BMW vehicle domain “${name}” from their source feature classifications. The PM can rename the group.`,
    requirements: items.sort((a, b) => b.score - a.score || b.frequency - a.frequency).slice(0, 10).map((r, index) => ({ ...r, rank: index + 1 }))
  })).filter(g => g.requirements.length).sort((a, b) => b.requirements[0].score - a.requirements[0].score);
}

export function validateCitations(groups, evidence) {
  const ids = new Set(evidence.map(r => r.evidenceId));
  return groups.flatMap(g => g.requirements).every(r => r.citations.length && r.citations.every(c => ids.has(c.evidenceId)));
}

export function draftEmail(requirement, config) {
  return `Subject: Feasibility review — ${requirement.feature}\n\nHello ${requirement.owner.name} team,\n\nFor the ${config.vehicle} in ${config.market}, we are evaluating this requirement:\n“${requirement.statement}”\n\nWhy it exists: ${requirement.whyExists}\nEvidence: ${requirement.frequency} unique relevant records; ${requirement.citations[0].file}, ${requirement.citations[0].sheet}, row ${requirement.citations[0].row} (plus ${Math.max(0, requirement.frequency - 1)} additional records).\n\nPlanning context: ${config.months}-month target, ${config.people} people, deadline importance ${config.importance}/10. The ${requirement.estimatedMonths}-month estimate shown in our tool is AI-generated and not a feasibility conclusion.\n\nCould you confirm whether this requirement is feasible, feasible with conditions, or not feasible? Please identify constraints, dependencies, timing implications, and any recommended wording changes.\n\nThank you.`;
}

