const DOMAIN_RULES = [
  ['Interior & Comfort', /seat|comfort|lumbar|climat|blower|acoustic|noise|audio|sound|belt|mirror|console|storage|interior|cabin|cupholder/i],
  ['Exterior & Utility', /exterior|roof|trunk|tailgate|door|light|paint|wheel|tire|luggage|cargo|compartment|fold/i],
  ['Digital Experience & Controls', /digital|app|bluetooth|carplay|android|connected|remote|mobile|phone|operat|control|touch|display|cluster|parking|automatic-hold|speed limit|button|owner's manual|camera|infotainment|idrive|navigation/i]
];

const OUTCOME_RULES = [
  ['Seating comfort', /seat|lumbar|belt/i], ['Cabin climate', /climat|blower|heating|ventilation/i],
  ['Cabin refinement', /acoustic|noise|audio|sound|interior design|comfort/i], ['Storage usability', /console|storage|cupholder|compartment/i],
  ['Cargo access', /trunk|tailgate|luggage|cargo|fold/i], ['Exterior expression', /exterior|paint|wheel|roof/i],
  ['Visibility & lighting', /light|mirror|camera|visibility/i], ['Connected access', /digital key|app|mobile|phone|bluetooth/i],
  ['Infotainment usability', /carplay|android|infotainment|idrive|touch|display|operating system|navigation/i],
  ['Parking confidence', /parking|park distance|camera/i], ['Driver controls', /control|button|cluster|speed limit|owner's manual|automatic-hold/i],
  ['Ride & handling', /handling|riding|chassis|steer|suspension|stability/i], ['Powertrain performance', /drivetrain|transmission|engine|range|charging|battery|efficiency/i],
  ['Braking confidence', /brake|pedal/i]
];

const ENTITY_RULES = [
  ['Software & Connected Services', /app|digital|bluetooth|carplay|connected|remote|operating system|display|touch|camera/i, 'Electrical/Electronic Engineering'],
  ['Interior Engineering', /seat|comfort|lumbar|climat|blower|console|storage|mirror|belt|audio|sound/i, 'Product Integration'],
  ['Chassis Engineering', /handling|riding|chassis|steer|brake|pedal|suspension|stability/i, 'Vehicle Dynamics'],
  ['E-Mobility Engineering', /electric|charging|battery|range|efficiency/i, 'Software & Connected Services'],
  ['Body Engineering', /exterior|roof|trunk|tailgate|door|luggage|compartment|space/i, 'Manufacturing']
];

const DEPENDENCY_RULES = [
  [/digital key|remote/i, /app|mobile|phone|bluetooth|connected/i], [/parking/i, /camera|park distance|display|sensor/i],
  [/luggage|cargo|trunk/i, /tailgate|fold|storage|suspension|battery/i], [/electric range/i, /charging|battery|efficiency/i],
  [/seat/i, /lumbar|climat|belt|comfort/i], [/infotainment|touch|operating/i, /display|carplay|android|control|owner's manual/i]
];

export const groupFor = feature => DOMAIN_RULES.find(([,rule]) => rule.test(feature))?.[0] || 'Driving & Powertrain';
export const outcomeFor = feature => OUTCOME_RULES.find(([,rule]) => rule.test(feature))?.[0] || `Improve ${feature}`;

export function entityFor(feature) {
  const match=ENTITY_RULES.find(([,rule])=>rule.test(feature));
  return { name:match?.[0]||'Product Integration', alternative:match?.[2]||'Product Owner', confidence:match?'medium':'low', reason:match?`The source feature classification “${feature}” matches this function’s typical ownership.`:'Ownership crosses domains and requires PM correction or confirmation.' };
}

const monthsFor = feature => /app|software|display|touch|operating|bluetooth|carplay|manual/i.test(feature)?6:/seat|console|storage|mirror|belt|audio|climat|control|camera/i.test(feature)?12:/chassis|suspension|body|roof|luggage|battery|drivetrain/i.test(feature)?24:15;
function requirementStatement(feature,records){const types=new Set(records.map(r=>r.feedbackType));if([...types].some(t=>/Difficult/i.test(t)))return `Make ${feature.toLowerCase()} easier and more predictable to use`;if([...types].some(t=>/Want/i.test(t)))return `Improve ${feature.toLowerCase()} to address documented customer requests`;return `Preserve and strengthen customer satisfaction with ${feature.toLowerCase()}`;}

export function buildModel(records,config,statuses={}) {
  const relevant=records.filter(r=>r.vehicle===config.vehicle&&r.market===config.market&&r.quality!=='low'&&r.feature);
  const byFeature=new Map();
  for(const record of relevant){if(!byFeature.has(record.feature))byFeature.set(record.feature,[]);byFeature.get(record.feature).push(record)}
  const maxFrequency=Math.max(1,...[...byFeature.values()].map(items=>new Set(items.map(x=>x.feedbackId)).size));
  const requirements=[...byFeature].map(([feature,items])=>{
    const unique=[...new Map(items.map(item=>[item.feedbackId,item])).values()];
    const months=monthsFor(feature),peopleNeeded=Math.max(2,Math.ceil(months/3));
    const frequencyScore=Math.round(unique.length/maxFrequency*100);
    const fitScore=Math.round(Math.min(100,(config.months*Math.max(1,config.people)/(months*peopleNeeded))*70));
    const importance=Number(config.importance)/10;
    let score=Math.round(frequencyScore*(.75-importance*.25)+fitScore*(.25+importance*.25));
    if(statuses[feature]==='not-feasible'||statuses[feature]==='pm-rejected')score=-1;
    if(statuses[feature]==='conditional')score-=12;
    const qualityCounts=unique.reduce((out,row)=>(out[row.quality]=(out[row.quality]||0)+1,out),{});
    return {
      id:`req-${feature.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/g,'')}`,feature,group:groupFor(feature),outcome:outcomeFor(feature),
      statement:requirementStatement(feature,items),problem:`Customer evidence concerning ${feature.toLowerCase()} indicates a product opportunity for ${config.vehicle} in ${config.market}.`,
      frequency:unique.length,score,scoreBreakdown:{frequency:frequencyScore,timeToMarketFit:fitScore,deadlineImportance:Number(config.importance)},
      estimatedMonths:months,estimatedPeople:peopleNeeded,fitScore,status:statuses[feature]||'not-checked',owner:entityFor(feature),
      confidence:unique.length>=10?'high':unique.length>=3?'medium':'low',evidenceQuality:qualityCounts,dependencies:[],
      citations:unique.slice(0,8).map(r=>({evidenceId:r.evidenceId,file:r.sourceFile,sheet:r.sheet,row:r.row,column:'Customer Feedback / Feature classification',excerpt:r.text,feedbackId:r.feedbackId})),
      whyExists:`${unique.length} unique, relevant ${config.market} feedback record${unique.length===1?'':'s'} support this requirement for ${config.vehicle}. Low-quality and duplicate classifications do not contribute to this count.`,
      rankBasis:`Deduplicated evidence frequency: ${unique.length} (${frequencyScore}/100 normalized). AI planning estimate: ${months} months with about ${peopleNeeded} people. Against the PM’s ${config.months}-month target, ${config.people}-person team and ${config.importance}/10 deadline importance, time-to-market fit is ${fitScore}/100.`,
      inferenceLabels:['Requirement wording: AI-derived','Outcome grouping: AI-inferred','Time-to-market fit: AI planning estimate','Ownership: AI-inferred']
    };
  }).filter(r=>r.frequency>0&&r.score>=0);

  for(const requirement of requirements){
    const dependencyRule=DEPENDENCY_RULES.find(([source])=>source.test(requirement.feature));
    if(dependencyRule)requirement.dependencies=requirements.filter(candidate=>candidate.id!==requirement.id&&dependencyRule[1].test(candidate.feature)).slice(0,3).map(candidate=>({id:candidate.id,feature:candidate.feature,label:'AI-inferred until stakeholder validation'}));
  }

  const groups=new Map();for(const requirement of requirements){if(!groups.has(requirement.group))groups.set(requirement.group,[]);groups.get(requirement.group).push(requirement)}
  return [...groups].map(([name,items])=>{
    const selected=items.sort((a,b)=>b.score-a.score||b.frequency-a.frequency).slice(0,10);
    const ranked=selected.map((r,index)=>{
      const above=index?` It ranks below “${selected[index-1].feature}” (${selected[index-1].score}) because its combined evidence and schedule score is lower.`:'';
      const below=index<selected.length-1?` It ranks above “${selected[index+1].feature}” (${selected[index+1].score}) because its combined score is higher.`:'';
      return {...r,rank:index+1,whyRanked:`${r.rankBasis} Final score: ${r.score}/100.${above}${below}`};
    });
    return {name,description:`BMW macro-domain containing evidence-derived outcomes such as ${[...new Set(ranked.map(r=>r.outcome))].slice(0,4).join(', ')}. The PM can rename, split, or merge this group.`,evidenceSummary:`${ranked.reduce((sum,r)=>sum+r.frequency,0)} summed unique-per-requirement evidence links across ${ranked.length} ranked requirements.`,dependencySummary:`${ranked.reduce((sum,r)=>sum+r.dependencies.length,0)} AI-inferred dependency links require stakeholder validation.`,requirements:ranked};
  }).filter(g=>g.requirements.length).sort((a,b)=>b.requirements[0].score-a.requirements[0].score);
}

export function validateCitations(groups,evidence){const ids=new Set(evidence.map(r=>r.evidenceId));return groups.flatMap(g=>g.requirements).every(r=>r.citations.length&&r.citations.every(c=>ids.has(c.evidenceId)))}

export function draftEmail(r,c){const dependencies=r.dependencies.length?r.dependencies.map(d=>d.feature).join(', '):'No dependencies have been validated; please identify any that apply.';return `Subject: Feasibility review — ${r.feature}\n\nHello ${r.owner.name} team,\n\nFor the ${c.vehicle} in ${c.market}, we are evaluating this requirement:\n“${r.statement}”\n\nWhy it exists: ${r.whyExists}\nEvidence: ${r.frequency} unique relevant records; ${r.citations[0].file}, ${r.citations[0].sheet}, row ${r.citations[0].row} (plus ${Math.max(0,r.frequency-1)} additional records).\nAI-inferred dependencies: ${dependencies}\n\nPlanning context: ${c.months}-month target, ${c.people} people, deadline importance ${c.importance}/10. The ${r.estimatedMonths}-month estimate shown in PM is AI-generated and not a feasibility conclusion.\n\nCould you confirm whether this requirement is feasible, feasible with conditions, or not feasible? Please identify constraints, dependencies, timing implications, and any recommended wording changes.\n\nThank you.`}

