import { buildModel, draftEmail, validateCitations } from './engine.js';

const state = { evidence: [], context: null, historical: [], groups: [], selected: 0, config: null, statuses: JSON.parse(localStorage.getItem('requirement-statuses') || '{}'), events: JSON.parse(localStorage.getItem('decision-events') || '[]'), activeRequirement: null };
const $ = id => document.getElementById(id);
const escapeHtml = value => String(value).replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const statusKey = feature => `${state.config.vehicle}|${state.config.market}|${feature}`;
const statusMap = () => Object.fromEntries(Object.entries(state.statuses).filter(([key]) => key.startsWith(`${state.config.vehicle}|${state.config.market}|`)).map(([key,value]) => [key.split('|').slice(2).join('|'),value]));

async function init() {
  $('importance').addEventListener('input', e => $('importance-output').value = `${e.target.value} / 10`);
  $('vehicle').addEventListener('change', updateVehicleIdentity);
  $('config-form').addEventListener('submit', event => { event.preventDefault(); if (state.evidence.length) generate(); });
  $('edit-config').addEventListener('click', () => { $('setup').classList.remove('hidden'); $('workspace').classList.add('hidden'); });
  $('rename-group').addEventListener('click', renameGroup);
  $('split-group').addEventListener('click', splitGroup);
  $('merge-group').addEventListener('click', mergeGroup);
  document.querySelectorAll('.nav').forEach(b => b.addEventListener('click', () => showView(b.dataset.view)));
  document.querySelectorAll('[data-close]').forEach(b => b.addEventListener('click', () => b.closest('dialog').close()));
  document.querySelectorAll('[data-report]').forEach(b=>b.addEventListener('click',()=>downloadReport(b.dataset.report)));
  renderMemory();
  checkOpenAIStatus();
  const [response,contextResponse,historyResponse] = await Promise.all([fetch('../data/evidence.json'),fetch('../data/context.json'),fetch('../data/historical-decisions.json')]);
  if (!response.ok || !contextResponse.ok || !historyResponse.ok) throw new Error(`Evidence stores failed to load. Start PM with â€œnode server.mjsâ€ from the repository root.`);
  const [payload,context,history] = await Promise.all([response.json(),contextResponse.json(),historyResponse.json()]);
  state.evidence = payload.records;
  state.context = context;
  state.historical = history.decisions.map(decision=>({id:decision.id,type:'historical-decision',title:decision.requirement,description:`${decision.productCycle} Â· ${decision.decisionStatus}. ${decision.pmReasoning}`,data:decision,at:decision.timestamp,provenance:decision.provenance}));
  renderMemory();
  populateMarkets();
  $('generate-button').disabled = false;
  $('generate-button').innerHTML = 'Generate evidence-backed requirements <span>â†’</span>';
}

async function checkOpenAIStatus(){
  try{
    const response=await fetch('/api/health');
    const status=await readApiResponse(response);
    if(status.apiVersion!=='pm-api-2')throw new Error('An outdated PM server is running. Stop it and restart â€œnode server.mjsâ€.');
    $('ai-status').innerHTML=`<span></span> ${status.openaiConfigured?`OpenAI ready Â· ${escapeHtml(status.model)}`:'OpenAI key required'}`;
    $('ai-status').classList.toggle('offline',!status.openaiConfigured);
  }catch(error){$('ai-status').innerHTML=`<span></span> ${escapeHtml(error.message)}`;$('ai-status').classList.add('offline')}
}

async function readApiResponse(response){
  const type=response.headers.get('content-type')||'';
  const text=await response.text();
  if(!type.includes('application/json')){
    if(response.status===404||/^Not found/i.test(text))throw new Error('PM API route not found. Stop the old/static server and start this app with â€œnode server.mjsâ€.');
    throw new Error(`PM API returned ${response.status} ${type||'without a content type'}.`);
  }
  let payload;try{payload=JSON.parse(text)}catch{throw new Error('PM API returned malformed JSON.')}
  if(!response.ok)throw new Error(payload.error||`PM API request failed (${response.status}).`);
  return payload;
}

function updateVehicleIdentity(){
  const labels={G60:'BMW 5 SERIES',F70:'BMW 1 SERIES',G70:'BMW 7 SERIES'};
  $('hero-code').textContent=$('vehicle').value;
  $('hero-label').textContent=`${labels[$('vehicle').value]} Â· PRODUCT CYCLE`;
  if(state.evidence.length)populateMarkets();
}

function populateMarkets(){
  const names={US:'United States',GB:'United Kingdom',DE:'Germany',CN:'China',JP:'Japan',KR:'South Korea',FR:'France',IT:'Italy',ES:'Spain',CA:'Canada'};
  const previous=$('market').value;
  const counts=new Map();
  for(const record of state.evidence){if(record.vehicle===$('vehicle').value)counts.set(record.market,(counts.get(record.market)||0)+1)}
  const markets=[...counts].filter(([code])=>code).sort((a,b)=>(a[0]==='US'?-1:b[0]==='US'?1:b[1]-a[1]));
  $('market').innerHTML=markets.map(([code,count])=>`<option value="${escapeHtml(code)}">${escapeHtml(names[code]||code)} Â· ${count.toLocaleString()} records</option>`).join('');
  if(markets.some(([code])=>code===previous))$('market').value=previous;
}

function addEvent(type, title, description, data={}) {
  state.events.unshift({ id: crypto.randomUUID(), type, title, description, data, at: new Date().toISOString(), provenance:'Genuine application event' });
  localStorage.setItem('decision-events', JSON.stringify(state.events));
  renderMemory();
}

function generate(event) {
  event?.preventDefault();
  state.config = { vehicle:$('vehicle').value, market:$('market').value, months:Number($('months').value), people:Number($('people').value), importance:Number($('importance').value) };
  const historicalEvidenceIds=state.historical.filter(event=>event.data.vehicle===state.config.vehicle&&event.data.market===state.config.market).flatMap(event=>event.data.supportingEvidence||[]);
  state.config.historyFeatures=[...new Set(historicalEvidenceIds.map(id=>state.evidence.find(record=>record.evidenceId===id)?.feature).filter(Boolean))];
  state.groups = buildModel(state.evidence, state.config, statusMap());
  state.selected = 0;
  addEvent('project-created', 'Product context evaluated', `${state.config.vehicle} Â· ${state.config.market} Â· ${state.config.months} months Â· ${state.config.people} people Â· deadline importance ${state.config.importance}/10`, state.config);
  addEvent('ranking-calculated', 'Requirements generated and ranked', `${state.groups.length} evidence-derived feature groups created. No engineering feasibility was assumed.`);
  $('setup').classList.add('hidden'); $('workspace').classList.remove('hidden'); $('memory').classList.add('hidden');
  document.querySelectorAll('.nav').forEach(n => n.classList.toggle('active', n.dataset.view === 'workspace'));
  render();
}

function showView(view) {
  if (view === 'memory') { $('setup').classList.add('hidden'); $('workspace').classList.add('hidden'); $('memory').classList.remove('hidden'); }
  else if (state.config) { $('setup').classList.add('hidden'); $('memory').classList.add('hidden'); $('workspace').classList.remove('hidden'); }
  document.querySelectorAll('.nav').forEach(n => n.classList.toggle('active', n.dataset.view === view));
}

function render() {
