      frequency:unique.length,score,scoreBreakdown:{frequency:frequencyScore,timeToMarketFit:fitScore,deadlineImportance:Number(config.importance),historicalDecisionBonus:historicalBonus},
      estimatedMonths:months,estimatedPeople:peopleNeeded,fitScore,status:statuses[feature]||'not-checked',owner:entityFor(feature),
