      citations:unique.slice(0,8).map(r=>({evidenceId:r.evidenceId,file:r.sourceFile,sheet:r.sheet,row:r.row,column:'Customer Feedback / Feature classification',excerpt:r.text,feedbackId:r.feedbackId})),
      whyExists:`${unique.length} unique, relevant ${config.market} feedback record${unique.length===1?'':'s'} support this requirement for ${config.vehicle}. Low-quality and duplicate classifications do not contribute to this count.`,
