    const result=await readApiResponse(response);
    result.stakeholderResponse=responseText;
    const detail=[result.conditions?.length?`<p><strong>Conditions:</strong> ${escapeHtml(result.conditions.join('; '))}</p>`:'',result.constraints?.length?`<p><strong>Constraints:</strong> ${escapeHtml(result.constraints.join('; '))}</p>`:'',result.time_impact?`<p><strong>Timing:</strong> ${escapeHtml(result.time_impact)}</p>`:'',result.suggested_modification?`<p><strong>Suggested change:</strong> ${escapeHtml(result.suggested_modification)}</p>`:''].join('');
    const approvable=['feasible','conditional'].includes(result.status);
    $('interpretation').innerHTML=`<div class="evidence-box"><h3>OPENAI INTERPRETATION Â· HUMAN CONFIRMATION REQUIRED</h3><p>Status: <strong>${escapeHtml(result.status.replaceAll('-',' '))}</strong> Â· ${Math.round(result.confidence*100)}% confidence</p><p>${escapeHtml(result.summary)}</p>${detail}<p class="model-trace">Model: ${escapeHtml(result.model)} Â· Response: ${escapeHtml(result.responseId||'not returned')}</p>${approvable?'<label class="approval-rationale"><strong>Human approval rationale</strong><textarea id="approval-rationale" placeholder="Explain why you approve this requirement."></textarea></label>':''}<div class="interpret-actions"><button id="confirm-response" class="secondary" ${result.status==='unclear'?'disabled':''}>${result.status==='unclear'?'Clarification required':result.status==='not-feasible'?'Confirm rejection & recalibrate group':'Confirm feasibility only'}</button>${approvable?'<button id="confirm-approve" class="primary">Approve requirement <span>â†’</span></button>':''}</div></div>`;
    if(result.status!=='unclear')$('confirm-response').onclick=()=>confirmResponse(r,result);
    if(approvable)$('confirm-approve').onclick=()=>{const rationale=$('approval-rationale').value.trim();if(!rationale){alert('Add the human approval rationale before approving.');return}confirmResponse(r,result,{approve:true,rationale})};
  }catch(error){$('interpretation').innerHTML=`<div class="api-error"><strong>OpenAI interpretation failed.</strong><br>${escapeHtml(error.message)}</div>`}
  finally{button.disabled=false;button.textContent='Process Feedback & Recalibrate'}
