  const after=state.groups.map(g=>({group:g.name,requirements:g.requirements.map(x=>({feature:x.feature,rank:x.rank,score:x.score,status:x.status}))}));
  addEvent('interpretation-confirmed',`PM confirmed: ${result.status.replaceAll('-',' ')}`,`${r.feature}. Stakeholder response: ${result.summary}`,{before,after,model:result.model,responseId:result.responseId,confidence:result.confidence,stakeholderResponse:result.stakeholderResponse,supportingQuotes:result.supporting_quotes,conditions:result.conditions,constraints:result.constraints,timeImpact:result.time_impact,suggestedModification:result.suggested_modification},'Engineering response Â· OpenAI interpretation Â· PM confirmation');
