const r = await tools.shell_command({
  command: "$path='C:\Users\iyert\Downloads\competitor_bmw_format.xlsx'
$zip=[IO.Compression.ZipFile]::OpenRead($path)
try {
  $shared=@()
  $s=$zip.GetEntry('xl/sharedStrings.xml')
  if($s){$rd=[IO.StreamReader]::new($s.Open());[xml]$sx=$rd.ReadToEnd();$rd.Dispose();foreach($si in $sx.sst.si){if($si.t){$shared += [string]$si.t}else{$shared += (($si.r|ForEach-Object{[string]$_.t}) -join '')}}}
  $wr=[IO.StreamReader]::new($zip.GetEntry('xl/workbook.xml').Open());[xml]$wb=$wr.ReadToEnd();$wr.Dispose()
  $rr=[IO.StreamReader]::new($zip.GetEntry('xl/_rels/workbook.xml.rels').Open());[xml]$rels=$rr.ReadToEnd();$rr.Dispose()
  foreach($sh in $wb.workbook.sheets.sheet){
    $rid=$sh.GetAttribute('id','http://schemas.openxmlformats.org/officeDocument/2006/relationships')
    $target=($rels.Relationships.Relationship|Where-Object{$_.Id -eq $rid}).Target
    $entryPath=if($target -like '/*'){$target.TrimStart('/')}else{'xl/'+$target.TrimStart('/')}
    $entry=$zip.GetEntry($entryPath)
    "SHEET: $($sh.name) [$entryPath]"
    $rd=[IO.StreamReader]::new($entry.Open());[xml]$xml=$rd.ReadToEnd();$rd.Dispose()
    foreach($row in @($xml.worksheet.sheetData.row)|Select-Object -First 12){
      $vals=@()
      foreach($c in $row.c){
        $col=([regex]::Match([string]$c.r,'^[A-Z]+')).Value
        $v=[string]$c.v
        if($c.t -eq 's' -and $v -match '^\d+$'){$v=$shared[[int]$v]}
        elseif($c.t -eq 'inlineStr'){$v=[string]$c.is.t}
        $vals += "$col=$v"
      }
      "row $($row.r): " + ($vals -join ' | ')
    }
  }
} finally {$zip.Dispose()}",
  workdir: "C:\Users\iyert\Final-Hack-EHL",
  timeout_ms: 30000
});
text(r);

