    foreach ($row in $rows | Select-Object -Skip 1) {
      $v = $row.Values
      if (-not $v['A'] -or -not $v['I']) { continue }
      $text = [string]$v['I']
      $generic = $text.Trim().Length -lt 35 -or $text -match '^(really )?(love|great|good|nice) (this|the) car[.! ]*$'
      $records.Add([ordered]@{
        evidenceId = "$($v['F'])-feedback-row-$($row.Row)"
