    return;
  }
  if (pathname === '/api/decision-events' && req.method === 'GET') {
    try {
      const lines=(await readFile(decisionEventsPath,'utf8')).split(/\r?\n/).filter(Boolean);
      sendJson(res,200,{events:lines.map(line=>JSON.parse(line))});
