/* ShinyButton port for the evidence-generation submit action */
@property --pm-gleam-angle{syntax:"<angle>";initial-value:0deg;inherits:false}
@property --pm-gleam-width{syntax:"<percentage>";initial-value:6%;inherits:false}
#generate-button.shiny-button{--gleam-base:#08131e;--gleam-accent:#1c69d4;--gleam-soft:#6fc6ff;isolation:isolate;position:relative;overflow:hidden;width:100%;min-height:50px;align-items:center;justify-content:center;padding:14px 20px;border:1px solid transparent;border-radius:6px!important;color:#fff;background:linear-gradient(var(--gleam-base),var(--gleam-base)) padding-box,conic-gradient(from var(--pm-gleam-angle),transparent 0,var(--gleam-accent) var(--pm-gleam-width),#fff calc(var(--pm-gleam-width) * 2),var(--gleam-soft) calc(var(--pm-gleam-width) * 3),transparent calc(var(--pm-gleam-width) * 4)) border-box;box-shadow:inset 0 0 0 1px #1c69d433,0 10px 26px #02070c66;animation:pm-gleam-sweep 3s linear infinite;transition:--pm-gleam-width .8s cubic-bezier(.25,1,.5,1),box-shadow .25s ease,transform .16s ease;cursor:pointer}
#generate-button.shiny-button::before,#generate-button.shiny-button::after{content:"";position:absolute;pointer-events:none;z-index:1}
#generate-button.shiny-button::before{inset:3px;border-radius:4px;background:radial-gradient(circle at 2px 2px,#ffffffb8 .6px,transparent .8px);background-size:4px 4px;mask-image:conic-gradient(from calc(var(--pm-gleam-angle) + 45deg),#000,transparent 11% 89%,#000);opacity:.22}
#generate-button.shiny-button::after{left:50%;top:50%;width:115%;aspect-ratio:1;translate:-50% -50%;background:linear-gradient(-50deg,transparent 43%,#1c69d488 49%,#d9f2ff99 50%,#1c69d455 51%,transparent 57%);mask-image:radial-gradient(circle at bottom,transparent 38%,#000);opacity:.45;animation:pm-gleam-sheen 7.5s linear infinite}
#generate-button.shiny-button .shiny-label{position:relative;z-index:2;display:flex;align-items:center;justify-content:space-between;width:100%;gap:18px;font-size:11px;font-weight:750;letter-spacing:.075em;text-transform:uppercase;text-shadow:0 1px 8px #000}
#generate-button.shiny-button .shiny-arrow{font-size:17px;line-height:1;color:#d8f2ff;transition:transform .25s ease}
#generate-button.shiny-button:is(:hover,:focus-visible){--pm-gleam-width:18%;outline:0;box-shadow:inset 0 0 0 1px #58b9ff55,0 0 0 4px #1c69d41f,0 15px 34px #02070c88}
#generate-button.shiny-button:is(:hover,:focus-visible) .shiny-arrow{transform:translateX(4px)}
#generate-button.shiny-button:active{transform:translateY(1px)}
#generate-button.shiny-button:disabled{opacity:.48;cursor:wait;animation-play-state:paused;box-shadow:inset 0 0 0 1px #ffffff14}
#generate-button.shiny-button:disabled::after{animation-play-state:paused;opacity:.15}
@keyframes pm-gleam-sweep{to{--pm-gleam-angle:360deg}}
@keyframes pm-gleam-sheen{to{rotate:360deg}}
@media(prefers-reduced-motion:reduce){#generate-button.shiny-button,#generate-button.shiny-button::after{animation:none!important;transition:none!important}#generate-button.shiny-button:is(:hover,:focus-visible) .shiny-arrow{transform:none}}

