@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&display=swap');

:root{
  --editorial-bg:#f4f7fb;
  --editorial-ink:#172230;
  --editorial-muted:#697687;
  --editorial-line:#cbd5df;
  --editorial-panel:#dfe8f1;
  --editorial-blue:#0669d7;
  --editorial-green:#148461;
}

*{box-sizing:border-box}
html{scroll-behavior:smooth;background:var(--editorial-bg)}
body{margin:0;background:var(--editorial-bg);color:var(--editorial-ink);font-family:Inter,"Helvetica Neue",Arial,sans-serif;font-size:13px}
button,input,select,textarea{font:inherit}
.hidden{display:none!important}
.app-main{min-height:100vh;margin:0!important;background:var(--editorial-bg)!important;background-image:none!important}
.eyebrow,.section-label{margin:0;color:#536173;font-size:9px;font-weight:600;letter-spacing:.2em;text-transform:uppercase}

/* Global navigation */
.app-header{position:sticky;top:0;z-index:30;display:grid;grid-template-columns:300px 1fr 230px;align-items:stretch;height:88px;padding:0 clamp(24px,4.5vw,58px);background:rgba(247,249,252,.97);border-bottom:1px solid var(--editorial-line);backdrop-filter:blur(14px)}
.nav-brand{display:flex!important;align-items:center;gap:14px;min-width:0!important;padding:0!important;color:var(--editorial-ink)!important;text-decoration:none!important}
.bmw-logo{width:44px!important;height:44px!important;flex:0 0 auto}
.nav-brand>span{display:grid;gap:4px}
.nav-brand strong{font-size:14px;font-weight:600;letter-spacing:-.01em}
.nav-brand small{color:var(--editorial-muted);font-size:10px}
.app-header nav{display:flex;align-items:stretch;justify-content:center;gap:12px}
.app-header .nav{position:relative;display:flex!important;grid-template-columns:none!important;align-items:center!important;gap:9px;min-width:116px!important;height:auto!important;padding:2px 14px 0!important;background:transparent!important;border:0!important;border-left:0!important;border-radius:0!important;color:#526071!important;font-size:11px!important;font-weight:400!important;letter-spacing:0!important;text-align:center!important;text-transform:none!important;cursor:pointer}
.app-header .nav:hover,.app-header .nav.active{color:var(--editorial-ink)!important}
.app-header .nav.active:after{content:"";position:absolute;right:12px;bottom:0;left:12px;height:3px;background:var(--editorial-blue)}
.app-header .nav-index{color:#667587!important;font-size:8px!important;font-weight:500!important}
.app-header .nav em{display:inline-grid;min-width:18px;height:18px;place-items:center;padding:0 5px;background:#dce5ee!important;color:#667485!important;border-radius:9px;font-size:8px;font-style:normal}
.header-account{display:flex;align-items:center;justify-content:flex-end;gap:14px;color:#354252;font-size:10px}
.header-account strong{display:grid;width:36px;height:36px;place-items:center;border:1px solid var(--editorial-line);border-radius:50%;font-size:10px;font-weight:500}
.app-header>.truth{position:absolute;right:56px;bottom:-24px;display:none}

/* Overview */
.overview-page{min-height:100vh;background:var(--editorial-bg)}
.editorial-hero{position:relative;isolation:isolate;min-height:545px;overflow:hidden;background:linear-gradient(90deg,#d7e3ed 0%,#cbd9e5 58%,#aebfce 100%)}
.editorial-hero:before{content:"";position:absolute;z-index:-2;inset:0 0 0 40%;background:url('./bmw-hero.jpg') center 58%/cover no-repeat;filter:saturate(.78) contrast(1.06)}
.editorial-hero:after{content:"";position:absolute;z-index:-1;inset:0;background:linear-gradient(90deg,#d6e2ec 0%,rgba(214,226,236,.98) 27%,rgba(214,226,236,.74) 43%,rgba(214,226,236,.05) 67%),linear-gradient(0deg,rgba(12,26,39,.18),transparent 38%)}
.hero-copy{position:relative;z-index:2;width:min(540px,46vw);padding:64px 0 40px clamp(28px,4.5vw,58px)}
.hero-copy h1{margin:30px 0 22px;color:var(--editorial-ink);font-size:clamp(48px,5.1vw,72px);font-weight:400;line-height:.98;letter-spacing:-.055em}
.hero-copy .sub{max-width:390px;margin:0;color:#344252;font-size:13px;line-height:1.75}
.hero-cta{display:inline-flex;align-items:center;gap:28px;margin-top:34px;color:var(--editorial-ink);font-size:11px;font-weight:600;text-decoration:none}
.hero-cta span{font-size:16px;font-weight:400}
.hero-caption{position:absolute;right:4.5vw;bottom:25px;left:4.5vw;display:flex;justify-content:space-between;color:white;font-size:7px;font-weight:600;letter-spacing:.2em;text-transform:uppercase;text-shadow:0 1px 8px #07111c}
.hero-credit{position:absolute;right:4.5vw;bottom:8px;color:rgba(255,255,255,.6);font-size:7px;text-decoration:none}

.product-context{padding:38px clamp(28px,4.5vw,58px) 36px;background:#f7f9fc;border-bottom:1px solid var(--editorial-line)}
.section-heading{display:flex;align-items:end;justify-content:space-between;gap:28px}
.section-heading h2{margin:14px 0 0;color:var(--editorial-ink);font-size:23px;font-weight:500;letter-spacing:-.025em}
.section-heading>p{margin:0 0 4px;color:var(--editorial-muted);font-size:10px}
.context-form{display:grid;grid-template-columns:1.25fr 1.12fr .58fr .58fr 1fr;gap:20px;margin-top:31px;align-items:end}
.context-form label{display:grid;grid-template-columns:1fr auto;gap:8px;color:#354151;font-size:8px;font-weight:600;letter-spacing:.13em;text-transform:uppercase}
.context-form label>select,.context-form label>input,.context-form .unit{grid-column:1/-1}
.context-form select,.context-form input[type=number]{width:100%;height:43px;padding:0 4px;background:transparent;color:#253140;border:0;border-bottom:1px solid #8290a0;border-radius:0;outline:0;font-size:11px;letter-spacing:0;text-transform:none}
.context-form select:focus,.context-form input:focus{border-bottom-color:var(--editorial-blue)}
.context-form .unit{display:flex;align-items:center;border-bottom:1px solid #8290a0}
.context-form .unit input{border:0}
.context-form .unit span{padding-right:8px;color:#778495;font-size:9px;font-weight:400;letter-spacing:0;text-transform:none}
.deadline-field output{color:#394757;font-size:10px;letter-spacing:0}
.context-form input[type=range]{grid-column:1/-1;width:100%;height:22px;margin:1px 0 0;padding:0;accent-color:var(--editorial-blue)}
.context-form .guardrail{grid-column:1/4;display:flex;align-items:center;gap:9px;margin:10px 0 0;color:#738092;font-size:9px;line-height:1.5}
.context-form .guardrail span{color:#2d5c8f;font-size:18px}
#generate-button{grid-column:5;width:100%;min-height:42px;margin-top:10px;padding:0 20px;background:var(--editorial-blue);border:1px solid var(--editorial-blue);border-radius:2px;color:#fff;font-size:11px;font-weight:500;box-shadow:0 2px 5px #0b3c7130;cursor:pointer}
#generate-button .shiny-label{display:flex;align-items:center;justify-content:space-between;gap:12px}
#generate-button:disabled{background:#a9b8c7;border-color:#a9b8c7;color:#eef3f7;cursor:wait;box-shadow:none}

.foundation-strip{display:grid;grid-template-columns:1.35fr repeat(3,1fr);padding:25px clamp(28px,4.5vw,58px);background:#dfe8f1}
.foundation-strip>div,.foundation-strip article{min-height:70px;padding:4px 26px;border-left:1px solid #c1ceda}
.foundation-strip>div{padding-left:0;border-left:0}
.foundation-strip strong{display:block;margin-top:10px;color:#24303d;font-size:12px;font-weight:500}
.foundation-strip article>span{color:#50657b;font-size:18px}
.foundation-strip article small{display:block;margin-top:9px;color:#7a8795;font-size:9px}
.app-footer{display:flex;justify-content:space-between;gap:20px;padding:19px clamp(28px,4.5vw,58px);color:#84909d;font-size:7px}

/* Requirements workspace */
.workspace-view{min-height:calc(100vh - 88px);background:var(--editorial-bg)}
.context-bar{display:flex;align-items:center;gap:32px;padding:36px clamp(28px,4.5vw,58px) 30px;background:#f7f9fc!important;color:var(--editorial-ink)!important;border-bottom:0!important}
.context-bar h2{margin:15px 0 0;color:var(--editorial-ink);font-size:30px;font-weight:400;letter-spacing:-.04em}
.context-bar>div:first-child{min-width:0;flex:1}
.context-bar>div:nth-child(2){display:flex!important;gap:0!important;margin-left:auto!important;padding:0!important;background:transparent!important;border:0!important}
.context-metric{min-width:90px!important;padding:2px 13px!important;border-left:0!important}
.context-metric small{color:#7c8897!important;font-size:7px!important;font-weight:500!important;letter-spacing:.13em!important}
.context-metric strong{margin-top:8px!important;color:#172230!important;font-size:14px!important;font-weight:500!important}
.context-metric strong span{color:#6e7b8a!important;font-size:8px!important;font-weight:400!important}
.context-bar .secondary{min-height:34px;padding:0 14px;background:#f7f9fc;color:#263342;border:1px solid #c8d2dc;border-radius:2px;font-size:10px;box-shadow:0 2px 5px #22364a10}
.integrity{display:flex;align-items:center;gap:24px;min-height:40px;margin:0!important;padding:0 clamp(28px,4.5vw,58px)!important;background:#e1eaf2!important;color:#74818f!important;border:0!important;border-top:1px solid #d1dbe4!important;border-bottom:1px solid #d1dbe4!important;font-size:8px!important;letter-spacing:0!important}
.integrity strong{color:#667483!important;font-weight:400!important}
.integrity span+span:before{display:none!important}
.integrity .status-dot{width:5px;height:5px;margin-right:-18px;background:var(--editorial-green);box-shadow:none}
.workspace-grid{display:grid;grid-template-columns:240px minmax(0,1fr);max-width:100%;min-height:calc(100vh - 260px);margin:0;background:transparent!important}
.workspace-grid>aside{padding:31px 20px 50px clamp(28px,4.5vw,58px);background:transparent!important;border-right:1px solid var(--editorial-line)!important}
.section-label{margin-bottom:23px}
.group-button{width:100%;margin:0 0 3px;padding:15px 13px!important;background:transparent!important;color:#24303d!important;border:0!important;border-left:2px solid transparent!important;border-bottom:0!important;text-align:left;box-shadow:none!important;cursor:pointer}
.group-button:hover{background:#e9eff5!important}
.group-button.active{background:#dde7f0!important;border-left-color:var(--editorial-blue)!important;color:#162230!important;box-shadow:none!important}
.group-button strong{font-size:10px!important;font-weight:500!important;letter-spacing:0!important;text-transform:none!important}
.group-button span{margin-top:7px;color:#7e8a98!important;font-size:8px!important}
.results{padding:31px clamp(28px,4.5vw,62px) 60px!important;background:transparent!important}
.results-head{display:flex;align-items:start;justify-content:space-between;gap:30px;padding:0 0 20px!important;border-bottom:1px solid var(--editorial-line)!important}
.results-head h2{margin:15px 0 0;color:var(--editorial-ink)!important;font-size:27px!important;font-weight:400;letter-spacing:-.035em;text-transform:none!important}
.group-metrics{display:flex!important;width:auto!important;margin:24px 0 0!important;background:transparent!important;border:0!important;border-radius:0!important}
.group-metrics>div{display:flex;align-items:center;gap:5px;min-width:0!important;padding:0 24px 0 0!important;border:0!important}
.group-metrics small{color:#7d8997!important;font-size:8px!important;font-weight:400!important;letter-spacing:0!important;text-transform:none!important}
.group-metrics strong{order:-1;margin:0!important;color:#4b5a69!important;font-size:9px!important;font-weight:500!important}
.group-actions{display:flex;gap:6px;margin-top:14px!important}
.group-actions .secondary{height:25px!important;padding:0 8px!important;background:transparent!important;color:#73808f!important;border:1px solid #d0d9e2!important;font-size:7px!important}
.result-count{min-width:100px;text-align:right}
.result-count strong{display:block;color:#192534!important;font-size:36px!important;font-weight:300!important;line-height:1}
.result-count span{display:block;margin-top:10px;color:#7a8694!important;font-size:7px!important;letter-spacing:0!important;text-transform:uppercase!important}
.requirement-list{display:grid;gap:0!important;margin-top:0!important}
.requirement{display:grid;grid-template-columns:34px minmax(0,1fr) auto!important;column-gap:8px!important;margin:0!important;padding:24px 0!important;background:transparent!important;border:0!important;border-bottom:1px solid var(--editorial-line)!important;border-radius:0!important;box-shadow:none!important}
.requirement:hover{background:transparent!important;transform:none!important}
.rank{display:block!important;width:34px!important;height:auto!important;padding-top:3px;background:transparent!important;color:#708091!important;border:0!important;border-radius:0!important;font-size:10px!important;text-align:left}
.rank span:before{content:""!important}
.requirement-main{min-width:0;padding:0 12px 0 0}
.outcome{display:block;margin:0!important;color:#5c6978!important;font-size:7px!important;font-weight:600!important;letter-spacing:.11em;text-transform:uppercase}
.requirement h3{max-width:700px;margin:11px 0 0!important;color:#172230!important;font-size:15px!important;font-weight:500!important;line-height:1.45!important;letter-spacing:-.012em!important}
.meta{display:flex;flex-wrap:wrap;gap:18px!important;margin-top:14px!important;color:#71808f!important}
.meta span{padding:0!important;background:transparent!important;color:#71808f!important;border:0!important;border-radius:0!important;font-size:8px!important;line-height:1!important;white-space:normal!important}
.meta span+span{border-left:0!important}
.meta strong{color:#5b6978!important;font-weight:400!important}
.meta .badge{color:var(--editorial-blue)!important;font-weight:600!important;text-transform:uppercase!important}
.card-reasoning{margin-top:20px!important;padding:0!important;border:0!important;color:#273442!important;font-size:10px!important}
.card-reasoning summary{width:max-content;color:var(--editorial-blue)!important;font-size:9px;cursor:pointer}
.card-reasoning[open]{width:100%;padding-bottom:0!important}
.card-reasoning p{max-width:none!important;margin:15px 0 0!important;padding:14px 16px;background:#dfe8f1;color:#344252;line-height:1.65!important}
.card-reasoning p+p{margin-top:0!important;padding-top:0}
.actions{align-self:end!important;display:flex!important;align-items:center!important;justify-content:flex-end!important;gap:8px!important;max-width:none!important;padding-bottom:1px}
.actions button{height:32px!important;padding:0 10px!important;background:transparent!important;color:#1f2d3b!important;border:0!important;border-radius:2px!important;font-size:8px!important;line-height:30px!important;letter-spacing:0!important;text-transform:none!important}
.actions .evidence-link{display:none}
.actions .primary-card-action{order:initial!important;padding:0 14px!important;background:#f8fafc!important;border:1px solid #c5d0db!important;box-shadow:0 2px 5px #24394d14!important}
.actions .primary-card-action:before{content:"♢";margin-right:8px;color:#375a7b;font-size:14px}
.actions .approve-action,.actions .reject-action,.actions .icon-action{width:32px!important;padding:0!important;font-size:0!important}
.actions .approve-action:after{content:"✓";font-size:15px}
.actions .reject-action:after{content:"×";font-size:19px}
.actions .icon-action[data-delete]{display:none}
.actions .icon-action[data-up]:after{content:"↑";font-size:13px}
.actions .icon-action[data-down]:after{content:"↓";font-size:13px}
.actions .move-action{display:none}
.actions .approval-state{color:var(--editorial-blue)!important;border:1px solid #a8c9ec!important}
.requirement:has(.badge.pm-rejected),.requirement:has(.badge.not-feasible){background:#fff0f1!important;border-left:2px solid #be2d3a!important;box-shadow:none!important}
.requirement:has(.badge.pm-rejected) .primary-card-action,.requirement:has(.badge.not-feasible) .primary-card-action{display:inline-block!important}
.requirement:has(.badge.pm-rejected) .reject-action,.requirement:has(.badge.not-feasible) .reject-action{background:#b72734!important;color:#fff!important}

/* Decision memory and drawers */
.memory{position:static!important;width:auto!important;max-width:1180px!important;height:auto!important;min-height:calc(100vh - 88px)!important;margin:0 auto!important;padding:58px clamp(28px,5vw,70px) 0!important;background:transparent!important;color:var(--editorial-ink)!important;border:0!important;box-shadow:none!important;animation:none!important}
.memory-head{padding:0 0 30px!important;border-bottom:1px solid var(--editorial-line)!important}
.memory h1{margin:16px 0 10px;color:var(--editorial-ink)!important;font-size:48px!important;font-weight:400;letter-spacing:-.05em}
.memory-head>p:not(.eyebrow){color:var(--editorial-muted)}
.memory-head input[type=search]{width:100%;margin-top:22px;padding:12px 0;background:transparent!important;color:var(--editorial-ink)!important;border:0!important;border-bottom:1px solid #95a2af!important}
.memory .event article{background:#e5edf4!important;color:var(--editorial-ink)!important;border:0!important;border-left:2px solid var(--editorial-blue)!important}
.memory .event time,.memory .event pre{color:#657382!important}

dialog{position:fixed!important;inset:0 0 0 auto!important;width:min(720px,94vw)!important;height:100dvh!important;max-height:100dvh!important;margin:0!important;padding:0!important;background:#f7f9fc!important;color:var(--editorial-ink)!important;border:0!important;border-left:1px solid var(--editorial-line)!important;box-shadow:-28px 0 80px #25364838!important}
dialog::backdrop{background:#18243155!important;backdrop-filter:blur(8px)}
.dialog-body{padding:48px 40px 70px!important}
.dialog-body h2,.dialog-body h3{color:var(--editorial-ink)!important}
.dialog-body textarea,.dialog-body input{background:white!important;color:var(--editorial-ink)!important;border:1px solid #bdc9d4!important}
.evidence-box,.decision-box,.email-composer{background:#e5edf4!important;color:#344252!important;border:1px solid #c8d4df!important}
.citation{border-color:#d0d9e2!important}.citation p{color:#465463!important}.citation code{color:#075fad!important}
.close{color:#24313f!important}

@media(max-width:1000px){
  .app-header{grid-template-columns:230px 1fr 80px;padding:0 24px}.header-account>span{display:none}.app-header .nav{min-width:100px!important;padding-inline:8px!important}
  .editorial-hero:before{inset:0 0 0 34%}.hero-copy{width:56vw;padding-left:32px}.hero-copy h1{font-size:54px}
  .context-form{grid-template-columns:repeat(2,minmax(0,1fr))}.deadline-field{grid-column:1/-1}.context-form .guardrail{grid-column:1}.context-form #generate-button{grid-column:2}
  .foundation-strip{grid-template-columns:1fr 1fr}.foundation-strip>div,.foundation-strip article{border-bottom:1px solid #c1ceda}
  .workspace-grid{grid-template-columns:205px minmax(0,1fr)}.workspace-grid>aside{padding-left:24px}.results{padding-inline:28px!important}
  .requirement{grid-template-columns:30px minmax(0,1fr)!important}.actions{grid-column:2;justify-content:flex-start!important;margin-top:16px}
}

@media(max-width:720px){
