  const offsets = [0];
  let cursor = chunks[0].length;
  for (let index = 1; index < objects.length; index += 1) {
    offsets[index] = cursor;
    const chunk = `${index} 0 obj\n${objects[index]}\nendobj\n`;
    chunks.push(chunk);
