const includesAny = (value, terms) => terms.some(term => value.includes(term));

export function fallbackReportAudience(requirement) {
  const text = [requirement.group, requirement.feature, requirement.outcome, requirement.statement, requirement.owner?.name, requirement.responsible_entity]
    .filter(Boolean).join(' ').toLowerCase();
  const technicalTerms = ['engineering', 'technical', 'software', 'digital', 'controls', 'chassis', 'powertrain', 'driving', 'body', 'interior', 'exterior', 'manufactur', 'integration', 'battery', 'charging', 'thermal', 'vehicle', 'safety', 'ux', 'hmi'];
  const gtmTerms = ['market', 'customer', 'brand', 'position', 'sales', 'launch', 'pricing', 'portfolio', 'retail', 'communication', 'premium', 'appearance', 'expression', 'experience', 'comfort', 'utility', 'cargo', 'luggage', 'range'];
  let technical = includesAny(text, technicalTerms);
  const gtm = includesAny(text, gtmTerms);
  if (!technical && !gtm) technical = true;
  const audiences = [technical && 'Technical', gtm && 'GTM'].filter(Boolean).join(' and ');
  return { technical, gtm, rationale:`Deterministic fallback routed this requirement to ${audiences} from its domain, wording, and responsible entity.` };
}

export function mergeReportAudienceAssignments(requirements, assignments = []) {
  const accepted = new Map();
  for (const assignment of assignments) {
    const id = String(assignment?.requirementId || assignment?.requirement_id || '');
    if (!id || typeof assignment.technical !== 'boolean' || typeof assignment.gtm !== 'boolean' || (!assignment.technical && !assignment.gtm)) continue;
    accepted.set(id, { technical:assignment.technical, gtm:assignment.gtm, rationale:String(assignment.rationale || '').trim() || 'Audience assigned from the requirement context.' });
  }
  return new Map(requirements.map(requirement => [requirement.id, accepted.get(requirement.id) || fallbackReportAudience(requirement)]));
}

export function partitionReportRequirements(requirements, routing) {
  const technical = requirements.filter(requirement => routing.get(requirement.id)?.technical);
  const gtm = requirements.filter(requirement => routing.get(requirement.id)?.gtm);
  const crossFunctional = requirements.filter(requirement => routing.get(requirement.id)?.technical && routing.get(requirement.id)?.gtm);
  const technicalOnly = requirements.filter(requirement => routing.get(requirement.id)?.technical && !routing.get(requirement.id)?.gtm);
  const gtmOnly = requirements.filter(requirement => routing.get(requirement.id)?.gtm && !routing.get(requirement.id)?.technical);
  return { technical, gtm, crossFunctional, technicalOnly, gtmOnly };
}

