import test from 'node:test';
import assert from 'node:assert/strict';
import { mergeReportAudienceAssignments, partitionReportRequirements } from '../src/report-routing.mjs';

test('PM partition contains every requirement exactly once while departmental reports overlap safely', () => {
  const requirements=[
    {id:'technical',statement:'Improve thermal control.',group:'Driving & Powertrain',owner:{name:'Powertrain Engineering'}},
    {id:'gtm',statement:'Clarify the customer market proposition.',group:'Exterior & Utility',owner:{name:'Product Marketing'}},
    {id:'both',statement:'Deliver a distinctive digital experience.',group:'Digital Experience & Controls',owner:{name:'Software Engineering'}}
  ];
  const routing=mergeReportAudienceAssignments(requirements,[
    {requirementId:'technical',technical:true,gtm:false,rationale:'Implementation scope.'},
    {requirementId:'gtm',technical:false,gtm:true,rationale:'Market scope.'},
    {requirementId:'both',technical:true,gtm:true,rationale:'Shared scope.'}
  ]);
  const result=partitionReportRequirements(requirements,routing);
  assert.deepEqual(result.technical.map(item=>item.id),['technical','both']);
  assert.deepEqual(result.gtm.map(item=>item.id),['gtm','both']);
  assert.deepEqual([...result.crossFunctional,...result.technicalOnly,...result.gtmOnly].map(item=>item.id).sort(),['both','gtm','technical']);
});

test('missing or invalid model assignments receive deterministic routing', () => {
  const requirements=[{id:'fallback',statement:'Improve luggage access for customers.',group:'Exterior & Utility',owner:{name:'Body Engineering'}}];
  const routing=mergeReportAudienceAssignments(requirements,[]);
  assert.equal(routing.get('fallback').technical,true);
  assert.equal(routing.get('fallback').gtm,true);
  assert.match(routing.get('fallback').rationale,/fallback/i);
});

